        assertEquals("translate", invokeNCName(parserFor("translate()")));
        assertEquals("boolean", invokeNCName(parserFor("boolean()")));
        assertEquals("not", invokeNCName(parserFor("not()")));
        assertEquals("true", invokeNCName(parserFor("true()")));
        assertEquals("false", invokeNCName(parserFor("false()")));
        assertEquals("null", invokeNCName(parserFor("null()")));
