        assertEquals("alpha", invokeNCName(parserFor("alpha")));
        assertEquals("alpha-beta_123", invokeNCName(parserFor("alpha-beta_123")));
        assertEquals("_name", invokeNCName(parserFor("_name")));
        assertEquals("n123", invokeNCName(parserFor("n123")));
    }

    @Test
    public void acceptsLongNcNameCharactersAndDoesNotTrimInput() throws Exception {
