package org.apache.commons.jxpath.ri.parser;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.fail;

import java.io.StringReader;
import java.lang.reflect.Field;
import java.lang.reflect.Method;

import org.junit.Test;

public class NCNameTests {

    private XPathParser parserFor(String input) {
        return new XPathParser(new StringReader(input));
    }

    private String invokeNCName(XPathParser parser) throws Exception {
        Method m = XPathParser.class.getDeclaredMethod("NCName");
        m.setAccessible(true);
        return (String) m.invoke(parser);
    }

    private Token currentToken(XPathParser parser) throws Exception {
        Field f = XPathParser.class.getDeclaredField("token");
        f.setAccessible(true);
        return (Token) f.get(parser);
    }

    @Test
    public void testBasicNcNameReturnsImage() throws Exception {
        XPathParser parser = parserFor("foo");
        assertEquals("foo", invokeNCName(parser));
    }

    @Test
    public void testNcNameWithColonAfterDotReturnsPrefixOnly() throws Exception {
        XPathParser parser = parserFor("a.b:c");
        assertEquals("a.b", invokeNCName(parser));
    }

    @Test
    public void testNcNameWithColonBeforeDotReturnsFullImage() throws Exception {
        XPathParser parser = parserFor("a:b.c");
        assertEquals("a:b.c", invokeNCName(parser));
    }

    @Test
    public void testNodeTokenIsAccepted() throws Exception {
        XPathParser parser = parserFor("node");
        assertEquals("node", invokeNCName(parser));
    }

    @Test
    public void testFunctionTokenIsAccepted() throws Exception {
        XPathParser parser = parserFor("last");
        assertEquals("last", invokeNCName(parser));
    }

    @Test
    public void testWhitespaceIsNotSilentlySkippedByNcName() throws Exception {
        XPathParser parser = parserFor("  foo");
        try {
            invokeNCName(parser);
            fail("Expected ParseException");
        } catch (Exception e) {
            Throwable cause = e.getCause() == null ? e : e.getCause();
            if (!(cause instanceof ParseException)) {
                throw e;
            }
        }
    }

    @Test
    public void testEmptyInputThrowsParseException() throws Exception {
        XPathParser parser = parserFor("");
        try {
            invokeNCName(parser);
            fail("Expected ParseException");
        } catch (Exception e) {
            Throwable cause = e.getCause() == null ? e : e.getCause();
            if (!(cause instanceof ParseException)) {
                throw e;
            }
        }
    }

    @Test
    public void testTokenStateIsCurrentTokenAfterSuccessfulParse() throws Exception {
        XPathParser parser = parserFor("prefix.name");
        String result = invokeNCName(parser);
        assertEquals("prefix.name", result);
        assertSame(currentToken(parser), parser.token);
    }
}

